'  float h = d.y;',
'  vec3 col = mix(uHor, uTop, smoothstep(0.0, 0.6, h));',
'  float sd = max(dot(d, normalize(uSunD)), 0.0);',
'  col += uSunC * (pow(sd, 600.0) * 1.4 + pow(sd, 14.0) * 0.3 + pow(sd, 3.0) * 0.08);',
'  float a = atan(d.z, d.x);',
'  float c = sin(a * 5.0 + h * 9.0 + uT * 0.006) * sin(a * 3.0 - h * 21.0 + 1.7) + 0.4 * sin(a * 13.0 + h * 40.0);',
'  col = mix(col, mix(uHor, vec3(1.0), 0.25), smoothstep(0.45, 1.1, c) * smoothstep(0.04, 0.22, h) * (1.0 - smoothstep(0.35, 0.7, h)) * 0.35);',
'  float au = uAur * smoothstep(0.15, 0.4, h) * (1.0 - smoothstep(0.45, 0.85, h));',
'  col += vec3(0.15, 0.55, 0.42) * au * (0.5 + 0.5 * sin(a * 7.0 + uT * 0.25 + sin(a * 3.0 + uT * 0.1) * 2.0)) * 0.35;',
'  float r1 = 0.04 + 0.022 * sin(a * 3.0 + 1.3) + 0.011 * sin(a * 7.0 + 0.4) + 0.006 * sin(a * 17.0 + 2.1);',
'  float r2 = 0.02 + 0.013 * sin(a * 5.0 + 2.7) + 0.007 * sin(a * 11.0 + 1.1);',
'  if (h < r1) col = mix(uRidge, uHor, 0.45 + 0.3 * smoothstep(0.0, r1, h));',
'  if (h < r2) col = mix(uRidge2, uHor, 0.3);',
'  if (h < 0.0) col = uHor;',
'  gl_FragColor = vec4(col, 1.0);',
