function initWind(D) {
W.base = rand(D.wind[0], D.wind[1]);
W.ang = (Math.random() < 0.5 ? 0 : Math.PI) + rand(-0.6, 0.6);
updateWind();
}
function updateWind() {
const t = MS.time;
W.speed = Math.max(0, W.base * (1 + 0.22 * Math.sin(t * 0.21) + 0.1 * Math.sin(t * 0.57 + 1.3)));
W.dir = W.ang + 0.16 * Math.sin(t * 0.13 + 2) + 0.06 * Math.sin(t * 0.41);
W.x = Math.cos(W.dir) * W.speed; W.z = Math.sin(W.dir) * W.speed;
U.uWind.value.set(W.x, W.z);
FLAGU.uWs.value = W.speed;
}

function integrate(b, dt) {
const rx = b.vx - W.x * WIND_MUL, ry = b.vy, rz = b.vz - W.z * WIND_MUL;
const k = AIR_K * Math.sqrt(rx * rx + ry * ry + rz * rz);
b.vx -= rx * k * dt; b.vy -= (ry * k + GRAV) * dt; b.vz -= rz * k * dt;
b.x += b.vx * dt; b.y += b.vy * dt; b.z += b.vz * dt;
}
