function rifleV0() { const r = RIFLES[save.rifle]; return r.v0 * (save.supp && !r.supp ? 0.94 : 1); }
function computeDope() {
const v0 = rifleV0(), sx = W.x, sz = W.z;
W.x = 0; W.z = 0;
const b = { x: 0, y: 0, z: 0, vx: v0, vy: 0, vz: 0 };
DOPE.drop[0] = 0; let k = 1;
for (let s = 0; s < 3000 && k < 33; s++) {
const px = b.x, py = b.y;
integrate(b, SIM);
while (k < 33 && b.x >= k * 25) { const f = (k * 25 - px) / (b.x - px); DOPE.drop[k] = -(py + (b.y - py) * f); k++; }
}
for (; k < 33; k++) DOPE.drop[k] = DOPE.drop[k - 1] * 1.3;
W.x = sx; W.z = sz;
DOPE.v0 = v0;
DOPE.base = DOPE.drop[4] / ZERO_RANGE;
}
function dropAt(r) { const f = clamp(r / 25, 0, 31.999), i = Math.floor(f); return lerp(DOPE.drop[i], DOPE.drop[i + 1], f - i); }
function holdMil(r) { return r < 1 ? 0 : (dropAt(r) / r - DOPE.base) * 1000; }
function clicksFor(r) { return clamp(Math.round(holdMil(r) / (CLICK * 1000)), 0, MAX_CLICKS); }
function zeroFor(clicks) {
const want = clicks * CLICK * 1000;
if (want <= 0) return ZERO_RANGE;
for (let r = ZERO_RANGE; r <= 800; r += 5) if (holdMil(r) >= want) return r;
return 800;
}

