pathPos[n * 3] = px; pathPos[n * 3 + 1] = heightAt(px, pz) + 0.6; pathPos[n * 3 + 2] = pz; n++;
pathPos[n * 3] = p[0]; pathPos[n * 3 + 1] = (R.t === 'drone' ? heightAt(p[0], p[1]) + R.fly : (p.length > 2 ? p[2] : heightAt(p[0], p[1]))) + 0.6; pathPos[n * 3 + 2] = p[1]; n++;
px = p[0]; pz = p[1];
