BC.scale = clamp(flight / 2.2, 0.05, 0.4); BC.dist = dist; BC.side = Math.random() < 0.5 ? -1 : 1;
BC.ix = PRED.x; BC.iy = PRED.y; BC.iz = PRED.z;
