for (let iz = 0; iz < b.nz; iz++) for (let ix = 0; ix < b.nx; ix++) {
if (b.state[(y * b.nz + iz) * b.nx + ix] === 0) { mx += ix + 0.5 - b.nx / 2; mz += iz + 0.5 - b.nz / 2; mn++; }
}
let dx = mn > 0 ? mx / mn : 0, dz = mn > 0 ? mz / mn : 0, len = Math.hypot(dx, dz);
