let snd = null, noiseBuf = null, audioRetryT = 0;
function hubAudio() {
try {
const r = typeof api.audio === 'function' ? api.audio() : null;
return r && r.ctx && r.out ? r : null;
} catch (err) { return null; }
}
function audioStart() {
if (snd || destroyed) return;
const h = hubAudio();
if (!h) return;
try {
const ac = h.ctx;
if (!noiseBuf || noiseBuf.sampleRate !== ac.sampleRate) {
const len = Math.floor(ac.sampleRate * 1.0);
noiseBuf = ac.createBuffer(1, len, ac.sampleRate);
const d = noiseBuf.getChannelData(0);
for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
}
const sg = ac.createGain(); sg.gain.value = 0;
const sf = ac.createBiquadFilter(); sf.type = 'lowpass'; sf.frequency.value = 240; sf.Q.value = 1.5;
const o1 = ac.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 40;
const o2 = ac.createOscillator(); o2.type = 'square'; o2.frequency.value = 60;
const g2 = ac.createGain(); g2.gain.value = 0.4;
o1.connect(sf); o2.connect(g2); g2.connect(sf); sf.connect(sg); sg.connect(h.out);
const lg = ac.createGain(); lg.gain.value = 0;
const lf = ac.createBiquadFilter(); lf.type = 'bandpass'; lf.frequency.value = 900; lf.Q.value = 1.4;
const l1 = ac.createOscillator(); l1.type = 'sawtooth'; l1.frequency.value = 220;
const l2 = ac.createOscillator(); l2.type = 'sawtooth'; l2.frequency.value = 331;
l1.connect(lf); l2.connect(lf); lf.connect(lg); lg.connect(h.out);
const src = ac.createBufferSource(); src.buffer = noiseBuf; src.loop = true;
const wf = ac.createBiquadFilter(); wf.type = 'lowpass'; wf.frequency.value = 420;
const wg = ac.createGain(); wg.gain.value = 0.018;
const rf = ac.createBiquadFilter(); rf.type = 'lowpass'; rf.frequency.value = 90;
const rg = ac.createGain(); rg.gain.value = 0;
src.connect(wf); wf.connect(wg); wg.connect(h.out);
src.connect(rf); rf.connect(rg); rg.connect(h.out);
o1.start(); o2.start(); l1.start(); l2.start(); src.start();
snd = { ac: ac, srcs: [o1, o2, l1, l2, src], nodes: [o1, o2, g2, sf, sg, l1, l2, lf, lg, src, wf, wg, rf, rg], sg: sg, sf: sf, o1: o1, o2: o2, lg: lg, lf: lf, l1: l1, rg: rg };
} catch (err) { snd = null; }
}
function audioStop() {
if (!snd) return;
const s = snd;
snd = null;
for (let i = 0; i < s.srcs.length; i++) { try { s.srcs[i].stop(); } catch (err) { /* already stopped */ } }
for (let i = 0; i < s.nodes.length; i++) { try { s.nodes[i].disconnect(); } catch (err) { /* already disconnected */ } }
}
function audioUpdate(dt) {
rumble = Math.max(0, rumble - dt * 0.6);
if (mode === 'playing' && !paused && !snd) { audioRetryT -= dt; if (audioRetryT <= 0) { audioRetryT = 2; audioStart(); } }
if (!snd) return;
try {
const t = snd.ac.currentTime, mv = clamp(P.speed / WALK, 0, 1.6);
snd.sg.gain.setTargetAtTime(0.026 + mv * 0.032 + (P.chargeT >= 0 ? 0.04 : 0), t, 0.08);
snd.o1.frequency.setTargetAtTime(38 + mv * 14, t, 0.1);
snd.o2.frequency.setTargetAtTime(57 + mv * 21, t, 0.1);
snd.sf.frequency.setTargetAtTime(200 + mv * 260, t, 0.1);
snd.lg.gain.setTargetAtTime(P.laserOn ? 0.045 : 0, t, 0.03);
snd.l1.frequency.setTargetAtTime(200 + P.heat * 2.2, t, 0.05);
snd.lf.frequency.setTargetAtTime(700 + P.heat * 9, t, 0.05);
snd.rg.gain.setTargetAtTime(rumble * 0.35, t, 0.1);
} catch (err) { /* ignore */ }
}

function moveSel(d) {
sel = clamp(sel + d, 0, DISTRICTS.length - 1);
api.tone(sel < save.unlocked ? 520 : 260, 0.05, { type: 'triangle', vol: 0.05 });
}
function buyUpgrade(i) {
if (i < 0 || i >= UPGRADES.length) return;
const lvl = save.up[i];
if (lvl >= 5 || save.salvage < UP_COST[lvl]) { api.tone(160, 0.12, { type: 'sawtooth', vol: 0.05 }); return; }
save.salvage -= UP_COST[lvl]; save.up[i] = lvl + 1;
writeSave();
api.tone(660, 0.1, { type: 'triangle', vol: 0.08 }); api.tone(990, 0.16, { type: 'triangle', vol: 0.08, delay: 0.08 });
}
function deploy() {
if (sel >= save.unlocked) { api.tone(160, 0.12, { type: 'sawtooth', vol: 0.05 }); return; }
startLevel(sel);
}
