let gTab = 0, gView = 0, hueDrag = false, gDirty = false;
function presetIdx(p) {
for (let i = 0; i < PAINTS.length; i++) { const q = PAINTS[i]; if (Math.abs(q.h - p.h) < 0.5 && Math.abs(q.s - p.s) < 0.01 && Math.abs(q.l - p.l) < 0.01) return i; }
return -1;
}
