function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
function lerp(a, b, t) { return a + (b - a) * t; }
function rand(a, b) { return a + random() * (b - a); }
function wrapA(a) { while (a > PI) a -= TAU; while (a < -PI) a += TAU; return a; }
function easeOut(t) { const u = 1 - t; return 1 - u * u * u; }
function smooth(a, b, x) { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }
function mulberry(seed) {
let a = seed >>> 0;
return function () {
a = (a + 0x6D2B79F5) >>> 0;
let t = a;
t = Math.imul(t ^ (t >>> 15), t | 1);
t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
}
function fmtTime(s) {
s = max(0, floor(s));
const m = floor(s / 60), r = s % 60;
return m + ':' + (r < 10 ? '0' : '') + r;
}
function css(hex) { return '#' + ('000000' + (hex >>> 0).toString(16)).slice(-6); }
function font(size, family, weight) { return (weight ? weight + ' ' : '') + size + 'px ' + family; }
function txt(ctx, s, x, y, size, family, color, align, maxW, weight) {
ctx.font = font(size, family, weight);
if (maxW) {
const w = ctx.measureText(s).width;
if (w > maxW) { size = max(8, floor(size * maxW / w)); ctx.font = font(size, family, weight); }
}
ctx.fillStyle = color; ctx.textAlign = align || 'center'; ctx.textBaseline = 'middle';
ctx.fillText(s, x, y);
}
function wrapText(ctx, s, maxW) {
const words = s.split(' '), lines = [];
let cur = '';
for (let i = 0; i < words.length; i++) {
const t = cur ? cur + ' ' + words[i] : words[i];
if (ctx.measureText(t).width > maxW && cur) { lines.push(cur); cur = words[i]; } else cur = t;
}
if (cur) lines.push(cur);
return lines;
}
function roundRectPath(ctx, x, y, w, h, r) {
const rr = max(0, min(r, w / 2, h / 2));
ctx.beginPath();
ctx.moveTo(x + rr, y);
ctx.arcTo(x + w, y, x + w, y + h, rr); ctx.arcTo(x + w, y + h, x, y + h, rr);
ctx.arcTo(x, y + h, x, y, rr); ctx.arcTo(x, y, x + w, y, rr);
ctx.closePath();
}
function panel(ctx, x, y, w, h, r) {
roundRectPath(ctx, x, y, w, h, r === undefined ? 18 : r);
ctx.fillStyle = UI.panel; ctx.fill();
ctx.lineWidth = 2; ctx.strokeStyle = UI.stroke; ctx.stroke();
}
