function addB(x, y, w, h, id, v) { btns.push({ x: x, y: y, w: w, h: h, id: id, v: v }); }
function idxOf(id) { for (let i = 0; i < btns.length; i++) if (btns[i].id === id) return i; return -1; }
function idxOfV(id, v) { for (let i = 0; i < btns.length; i++) if (btns[i].id === id && btns[i].v === v) return i; return -1; }
function wCost(w, f) { const m = f - 1, d = MONS[m], c = [[m, 0, 3], [m, WPN[w].mat, 1]]; if (d.mats.length > 4) c.push([m, 4, 1]); return { mats: c, sig: 100 * d.tier }; }
