function upCost(f, lv) { if (f === 0) return { mats: [], sig: 80 * (lv + 1) }; const m = f - 1; return { mats: [[m, 0, lv + 2]], sig: 60 * MONS[m].tier * (lv + 1) }; }
function canPay(c) { if (save.sig < c.sig) return false; for (let i = 0; i < c.mats.length; i++) { const e = c.mats[i]; if (save.mats[e[0]][e[1]] < e[2]) return false; } return true; }
function pay(c) { save.sig -= c.sig; for (let i = 0; i < c.mats.length; i++) { const e = c.mats[i]; save.mats[e[0]][e[1]] -= e[2]; } }
