if (c === 'Digit1' || c === 'Digit2' || c === 'Digit3' || c === 'Digit4') { if (!rep) { campTab = c.charCodeAt(5) - 49; campDirty = true; buildCamp(); focus = defaultFocus(); uiSfx(true); } return; }
if (c === 'ArrowUp' || c === 'KeyW') navFocus(0, -1);
else if (c === 'ArrowDown' || c === 'KeyS') navFocus(0, 1);
else if (c === 'ArrowLeft' || c === 'KeyA') navFocus(-1, 0);
else if (c === 'ArrowRight' || c === 'KeyD') navFocus(1, 0);
