function campClick(x, y) { if (campDirty) buildCamp(); const i = campHit(x, y); if (i >= 0) { focus = i; activate(btns[i]); } }
function campHover(x, y) { if (campDirty) return; const i = campHit(x, y); if (i >= 0 && i !== focus) focus = i; }
