let snd = null, noiseBuf = null, audioRetryT = 0;
function hubAudio() {
try { const r = typeof api.audio === 'function' ? api.audio() : null; return r && r.ctx && r.out ? r : null; } catch (err) { return null; }
}
function audioStart() {
if (snd || destroyed) return;
const h = hubAudio();
if (!h) return;
try {
const ac = h.ctx;
if (!noiseBuf || noiseBuf.sampleRate !== ac.sampleRate) {
const len = floor(ac.sampleRate * 1.5);
noiseBuf = ac.createBuffer(1, len, ac.sampleRate);
const d = noiseBuf.getChannelData(0);
for (let i = 0; i < len; i++) d[i] = random() * 2 - 1;
}
const src = ac.createBufferSource(); src.buffer = noiseBuf; src.loop = true;
const af = ac.createBiquadFilter(); af.type = 'lowpass'; af.frequency.value = Z.d ? Z.d.snd[0] : 500; af.Q.value = 0.7;
const ag = ac.createGain(); ag.gain.value = 0;
src.connect(af); af.connect(ag); ag.connect(h.out);
const gf = ac.createBiquadFilter(); gf.type = 'bandpass'; gf.frequency.value = 160; gf.Q.value = 2;
const gg = ac.createGain(); gg.gain.value = 0;
src.connect(gf); gf.connect(gg); gg.connect(h.out);
const o1 = ac.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 55;
const o2 = ac.createOscillator(); o2.type = 'sawtooth'; o2.frequency.value = 55.7;
const df = ac.createBiquadFilter(); df.type = 'lowpass'; df.frequency.value = 240;
const dg = ac.createGain(); dg.gain.value = 0;
o1.connect(df); o2.connect(df); df.connect(dg); dg.connect(h.out);
const o3 = ac.createOscillator(); o3.type = 'triangle'; o3.frequency.value = 300;
const cg = ac.createGain(); cg.gain.value = 0;
o3.connect(cg); cg.connect(h.out);
src.start(); o1.start(); o2.start(); o3.start();
snd = { ac: ac, srcs: [src, o1, o2, o3], nodes: [src, af, ag, gf, gg, o1, o2, df, dg, o3, cg], ag: ag, gg: gg, gf: gf, dg: dg, df: df, o3: o3, cg: cg };
} catch (err) { snd = null; }
}
function audioStop() {
if (!snd) return;
const s = snd;
snd = null;
for (let i = 0; i < s.srcs.length; i++) { try { s.srcs[i].stop(); } catch (err) { /* already stopped */ } }
for (let i = 0; i < s.nodes.length; i++) { try { s.nodes[i].disconnect(); } catch (err) { /* gone */ } }
}
function audioUpdate(dt) {
if (mode === 'playing' && !paused && !snd) { audioRetryT -= dt; if (audioRetryT <= 0) { audioRetryT = 2; audioStart(); } }
if (!snd) return;
try {
const ac = snd.ac;
if (ac.state !== 'running') return;
const t = ac.currentTime;
snd.ag.gain.setTargetAtTime(Z.d ? Z.d.snd[1] * 0.05 : 0.02, t, 0.5);
let fight = 0, growl = 0;
if (mon && mon.alive && mon.aware && mon.state !== 'rest' && mon.state !== 'sleep') {
const d = hypot(mon.x - P.x, mon.z - P.z);
fight = d < 80 ? 0.03 + (mon.rage > 0 ? 0.02 : 0) : 0;
growl = mon.state === 'atk' && mon.ph === 0 ? 0.12 * mon.tele * clamp(1 - d / 60, 0, 1) : 0;
}
const pulse = 0.6 + 0.4 * sin(animT * (mon && mon.rage > 0 ? 9 : 5.5));
snd.dg.gain.setTargetAtTime(fight * pulse, t, 0.08);
snd.df.frequency.setTargetAtTime(200 + fight * 4000, t, 0.3);
snd.gg.gain.setTargetAtTime(growl, t, 0.05);
snd.gf.frequency.setTargetAtTime(mon ? 220 / sqrt(mon.s) : 160, t, 0.2);
snd.cg.gain.setTargetAtTime(P.state === 'charge' ? 0.025 + P.chLv * 0.01 : 0, t, 0.04);
snd.o3.frequency.setTargetAtTime(300 + P.chLv * 160 + P.chargeT * 60, t, 0.05);
} catch (err) { /* ignore */ }
}

