e1.type = 'sawtooth'; e2.type = 'triangle'; e1.frequency.value = 48; e2.frequency.value = 24.3;
elp.type = 'lowpass'; elp.frequency.value = 300; elp.Q.value = 2; eg.gain.value = 0.02;
e1.connect(elp); e2.connect(elp); elp.connect(eg); eg.connect(master);
