ns.connect(nbp); nbp.connect(ng); ng.connect(master);
const l1 = ctx.createOscillator(), l2 = ctx.createOscillator(), lbp = ctx.createBiquadFilter(), lg = ctx.createGain();
l1.type = 'sawtooth'; l1.frequency.value = 170; l2.type = 'square'; l2.frequency.value = 341;
lbp.type = 'bandpass'; lbp.frequency.value = 1100; lbp.Q.value = 3; lg.gain.value = 0;
l1.connect(lbp); l2.connect(lbp); lbp.connect(lg); lg.connect(master);
