tOsc.type = 'sine'; tOsc.frequency.value = 420; tg.gain.value = 0;
tOsc.connect(tg); tg.connect(master);
const a1 = ctx.createOscillator(), a2 = ctx.createOscillator(), ag = ctx.createGain();
a1.type = 'sine'; a1.frequency.value = 55; a2.type = 'sine'; a2.frequency.value = 82.6; ag.gain.value = 0.022;
a1.connect(ag); a2.connect(ag); ag.connect(master);
