au.l1.frequency.setTargetAtTime(165 + heat * 110, t, 0.05);
au.l2.frequency.setTargetAtTime(331 + heat * 220 + Math.sin(gameT * 30) * 6, t, 0.05);
au.tg.gain.setTargetAtTime(tractorOn && fly ? 0.012 + pulling * 0.02 : 0, t, 0.1);
