function radarDot(c, cx, cy, R, scale, x, y, z, col, size, clampEdge, shape) {
const rx = x - ship.pos.x, ry = y - ship.pos.y, rz = z - ship.pos.z;
let px = (rx * RIGHT.x + ry * RIGHT.y + rz * RIGHT.z) * scale, pz = -(rx * FWD.x + ry * FWD.y + rz * FWD.z) * scale;
const up = (rx * UPW.x + ry * UPW.y + rz * UPW.z) * scale;
const d = Math.hypot(px, pz);
if (d > R - 4) { if (!clampEdge) return; px *= (R - 4) / d; pz *= (R - 4) / d; }
const sx = cx + px, sy = cy + pz, oy = clamp(-up * 0.5, -12, 12);
if (Math.abs(oy) > 1.5) { c.strokeStyle = col; c.globalAlpha = 0.5; c.lineWidth = 1; c.beginPath(); c.moveTo(sx, sy); c.lineTo(sx, sy + oy); c.stroke(); c.globalAlpha = 1; }
c.fillStyle = col; c.strokeStyle = col;
if (shape === 1) c.fillRect(sx - size, sy + oy - size, size * 2, size * 2);
else if (shape === 2) { c.lineWidth = 2; c.beginPath(); c.arc(sx, sy + oy, size, 0, TAU); c.stroke(); } else if (shape === 3) {
c.beginPath(); c.moveTo(sx, sy + oy - size); c.lineTo(sx + size, sy + oy + size); c.lineTo(sx - size, sy + oy + size); c.closePath(); c.fill();
} else c.fillRect(sx - size / 2, sy + oy - size / 2, size, size);
}
function drawRadar(c) {
const t = touch.on, R = t ? 58 : 74, cx = t ? VW - R - 16 : VW - R - 18, cy = t ? 112 + R : VH - R - 18;
const range = 320, scale = R / range;
c.fillStyle = 'rgba(10,16,30,0.72)'; c.beginPath(); c.arc(cx, cy, R, 0, TAU); c.fill();
c.strokeStyle = 'rgba(95,224,255,0.25)'; c.lineWidth = 1;
c.beginPath(); c.arc(cx, cy, R, 0, TAU); c.stroke();
c.beginPath(); c.arc(cx, cy, R * 0.5, 0, TAU); c.stroke();
c.beginPath(); c.moveTo(cx - R, cy); c.lineTo(cx + R, cy); c.moveTo(cx, cy - R); c.lineTo(cx, cy + R); c.stroke();
c.fillStyle = 'rgba(95,224,255,0.08)';
c.beginPath(); c.moveTo(cx, cy); c.arc(cx, cy, R, -Math.PI / 2 - 0.55, -Math.PI / 2 + 0.55); c.closePath(); c.fill();
for (let i = 0; i < rocks.length; i++) {
const rk = rocks[i];
if (!rk.alive) continue;
radarDot(c, cx, cy, R, scale, rk.pos.x, rk.pos.y, rk.pos.z, rk.scanT > 0 && !rk.giant ? ORES[rk.ore].col : rk.giant ? 'rgba(200,210,230,0.7)' : 'rgba(170,180,200,0.45)', rk.giant ? 4 : 2.2, false, 0);
}
for (let i = 0; i < CH_CAP; i++) if (chActive[i] && chOre[i] >= 0) radarDot(c, cx, cy, R, scale, chX[i], chY[i], chZ[i], ORES[chOre[i]].col, 1.6, false, 0);
for (let i = 0; i < DR_CAP; i++) { const d = drones[i]; if (d.alive) radarDot(c, cx, cy, R, scale, d.pos.x, d.pos.y, d.pos.z, UI.danger, 4, d.aggro, 3); }
if (stationIdx >= 0) { const p = stationObjs[stationIdx].grp.position; radarDot(c, cx, cy, R, scale, p.x, p.y, p.z, UI.hi, 4, true, 1); }
for (let i = 0; i < 2; i++) { const g = gateObjs[i]; if (g.active) radarDot(c, cx, cy, R, scale, g.pos.x, g.pos.y, g.pos.z, g.locked ? UI.danger : UI.cyan, 5, true, 2); }
c.fillStyle = UI.head; c.beginPath(); c.moveTo(cx, cy - 6); c.lineTo(cx + 4.5, cy + 4); c.lineTo(cx - 4.5, cy + 4); c.closePath(); c.fill();
txt(c, '320 m', cx + R - 4, cy + R - 2, 9, FONT_M, UI.dim, 'right');
}
