chip(c, cx, cy, cw, ch, flying ? 'FLYING' : owned ? 'SWITCH' : fmtN(s.price) + ' cr', flying ? UI.ok : owned ? UI.cyan : prof.cr >= s.price ? UI.hi : UI.danger);
