function clamp(v,a,b) {return v<a?a:v>b?b:v;}
function lerp(a,b,t) {return a+(b-a)*t;}
function rand(a,b) {return a+rnd()*(b-a);}
function irand(a,b) {return a+floor(rnd()*(b-a+1));}
function hash2(x,z) {const s=sin(x*127.1+z*311.7)*43758.5453;return s-floor(s);}
function hash3(x,y,z) {const s=sin(x*12.9898+y*78.233+z*37.719)*43758.5453;return s-floor(s);}
