'varying vec3 vCol; varying vec3 vLamp; varying vec3 vW; varying vec3 vN; varying vec2 vUv; varying vec2 vEm; varying float vFd;',
'void main() {',
'vec4 w=modelMatrix*vec4(position,1.0);',
'vW=w.xyz; vN=normal; vUv=uv; vCol=aCol;',
'float f=dot(vec4(equal(vec4(aMisc.x),vec4(0.0,1.0,2.0,3.0))),uFlick);',
'vLamp=aLamp*f; vEm=vec2(aMisc.y,f);',
'vec4 mv=viewMatrix*w; vFd=length(mv.xyz);',
'gl_Position=projectionMatrix*mv;',
'}',
