'uniform sampler2D uMap;',
'varying vec3 vCol; varying vec3 vLamp; varying vec3 vW; varying vec3 vN; varying vec2 vUv; varying vec2 vEm; varying float vFd;',
'void main() {',
'vec3 t=texture2D(uMap,vUv).rgb;',
'vec3 c=t*vCol*(lightAt(vW,normalize(vN))+vLamp);',
