'else if (aAnim.y<0.0) { p.y+=sin(ph*2.0)*aAnim.y; }',
'#ifdef USE_INSTANCING',
'mat4 m=modelMatrix*instanceMatrix;',
'#else',
'mat4 m=modelMatrix;',
'#endif',
'vec4 w=m*vec4(p,1.0);',
'vW=w.xyz; vN=normalize((m*vec4(normal,0.0)).xyz);',
'vCol=aCol; vGlow=aAnim.z; vInst=inst;',
