const ia=i+QA[k],jb=j+QB[k],a=ia/su,c=jb/sv;
let x=ox+ux*a+vx*c,y=oy+uy*a+vy*c,z=oz+uz*a+vz*c;
if (jit&&ia>0&&ia<su&&jb>0&&jb<sv) {const h=(hash3(x,y,z)-0.4)*jit;x+=nx*h;y+=ny*h;z+=nz*h;}
