if (ny>0.5||ny<-0.5) this.u.push(x/CS,z/CS);else if (nx>0.5||nx<-0.5) this.u.push(z/CS,y/CS);else this.u.push(x/CS,y/CS);
const f=em?1:aoAt(x,y,z,ny);
