b.vx=0;b.vy=0;b.vz=0;b.kx=0;b.kz=0;b.pitch=0;b.flip=0;
b.hp=b.max=D.hp*hpScale();b.st=S_CHASE;b.stT=0;b.cd=rand(0.4,1.2);b.ph=rnd()*TAU;b.flash=0;b.burn=0;b.gb=0;
