if (de<2.8&&visor.length<7) for (let k=0;k<2;k++) visor.push({x: rand(120,840),y: rand(80,520),r: rand(30,70),t: 0,dur: rand(1.8,3),s: rnd()});
if (de<6) addShake(0.08);
