if (Q.on&&!Q.dead&&!Q.under) for (let k=0;k<3;k++) {if (!Q.sacs[k].on) continue;sacPos(k);const dx=SP.x-x,dy=SP.y-y,dz=SP.z-z;if (dx*dx+dy*dy+dz*dz<(rad+0.8)*(rad+0.8)) hitQueenSac(k,dmg*0.6,KIND_BLAST);}
