f.t-=dt;
if (f.t<=0) {f.on=false;continue;}
for (let k=0;k<3;k++) {const a=rnd()*TAU,r=sqrt(rnd())*3;glow.add(f.x+cos(a)*r,0.1,f.z+sin(a)*r,rand(-0.3,0.3),rand(1.5,3.5),rand(-0.3,0.3),rand(0.4,0.8),rand(0.4,0.7),0.1,1,0.6,0.2,0.9,-1.5,1,4);}
