for (let j=0;j<L.hives.length;j++) {const n=L.hives[j];if (n.on) {const dx=n.x-f.x,dz=n.z-f.z;if (dx*dx+dz*dz<16) hitNest(n,10,KIND_FIRE,n.pod);}}
if (Q.on&&!Q.dead&&!Q.under) {const dx=Q.x-f.x,dz=Q.z-f.z;if (dx*dx+dz*dz<20) for (let k=0;k<3;k++) if (Q.sacs[k].on) {hitQueenSac(k,4,KIND_FIRE);break;}}
