for (let i=0;i<WEAPONS.length;i++) {if (!hasW(i)) continue;if (WEAPONS[i].res>=0&&WS[i].res<WEAPONS[i].max) return true;if (WEAPONS[i].flame&&WS[i].mag<ST[i].mag) return true;}
