if (o.t>0.35&&d<5&&P.down<=0) {const s=min(d,(5+16*(1-d/5))*dt);o.x+=dx/d*s;o.y+=dy/d*s;o.z+=dz/d*s;o.vx*=0.9;o.vz*=0.9;}
