const l=sqrt(dx*dx+dz*dz)||1;
P.dash-=1;P.dashT=DASH_T;P.dashX=dx/l;P.dashZ=dz/l;P.inv=max(P.inv,0.3);P.slideT=0;
noise(0.18,0.13,2400);tone(300,0.12,'sine',0.05,700);
for (let k=0;k<8;k++) dust.add(P.x+rand(-0.4,0.4),P.y+rand(0.2,1.2),P.z+rand(-0.4,0.4),-P.dashX*3,rand(0,1),-P.dashZ*3,0.5,0.3,0.9,0.6,0.75,0.9,0.35,0,2,0);
