if (k==='burn') nearestOT(L.nests,'on',true,1.8);
else if (k==='power') nearestOT(L.gens,'done',false,2.6);
else if (k==='cores') nearestOT(L.cores,'got',false,1.6);
else if (k==='defend'&&L.lift) {OT.x=L.lift.x;OT.y=1.5;OT.z=L.lift.z;OT.on=true;}
else if (k==='queen'&&Q.on&&!Q.dead) {OT.x=Q.x;OT.y=4*Q.sc;OT.z=Q.z;OT.on=true;}
else if (k==='extract'&&L.exit) {OT.x=L.exit.x;OT.y=1.5;OT.z=L.exit.z;OT.on=true;}
