finishInst(coreMesh,n);n=0;
for (let i=0;i<MAX_ORBS;i++) {const o=orbs[i],s=0.8+sin(animT*8+i)*0.2;if (o.on) n=put(orbMesh,n,o.x,o.y,o.z,animT*2,animT*3+i,0,s,s,s,animT*4+i,2,0);}
