lip = true;
const a = (Math.random() < 0.5 ? -1 : 1) * (0.15 + Math.random() * 0.25), c = Math.cos(a), s = Math.sin(a);
const vx = ball.vx * c - ball.vy * s, vy = ball.vx * s + ball.vy * c;
ball.vx = vx * 0.8; ball.vy = vy * 0.8;
tone(1150, 0.04, { type: 'sine', vol: 0.08 });
tone(820, 0.05, { type: 'sine', vol: 0.07, delay: 0.05 });
