if (speed() > 12) {
drag.on = false;
ball.sx = px; ball.sy = py;
phase = 'roll'; phaseT = 0; restT = 0; rollT = 0; lip = false;
tone(250, 0.05, { type: 'square', vol: 0.07 });
} else { ball.vx = 0; ball.vy = 0; }
