drag.on = false;
try { if (canvas.hasPointerCapture(e.pointerId)) canvas.releasePointerCapture(e.pointerId); } catch (err) { /* already released */ }
if (cancel || paused || state !== 'playing' || phase !== 'aim') return;
const p = toLogical(e);
const dx = ball.x - p.x, dy = ball.y - p.y, L = Math.hypot(dx, dy);
