const onPointerUp = (e) => endDrag(e, false);
const onPointerCancel = (e) => endDrag(e, true);
const onContext = (e) => e.preventDefault();
function onBlur() { clearKeys(); if (ON.live) { drag.on = false; return; } setPaused(true); }
