let p = null;
try { p = api.net.open({ maxPlayers: NSEAT, modeLabel: 'Mini golf' }); } catch (e) { p = null; }
if (!p || typeof p.then !== 'function') { ON.note = "Online play didn't start. Try again."; ON.noteOk = false; return; }
