for (let q = 0; q < pl.length; q++) {
const p = pl[q], i = p && typeof p === 'object' ? p.index : -1;
if (!(i >= 0 && i < NSEAT) || i !== (i | 0)) continue;
ON.name[i] = String(p.name || '').slice(0, 12) || 'Player ' + (i + 1);
ON.seen[i] = true; ON.conn[i] = p.connected !== false;
}
ON.seen[ON.me] = ON.conn[ON.me] = true;
ON.m = 0; ON.course = 0; ON.rdy = 0; ON.iWant = false; ON.recM = -1; ON.note = ''; ON.hp = ''; ON.lag.fill(0);
