let best = 1e9, w = 0;
calcTot();
if (!early) {
for (let i = 0; i < NSEAT; i++) if (ON.inM[i] && !ON.gone[i] && ON.tot[i] < best) best = ON.tot[i];
for (let i = 0; i < NSEAT; i++) if (ON.inM[i] && !ON.gone[i] && ON.tot[i] === best) w |= 1 << i;
}
const s = scArr(), g = mask(ON.gone);
