if (!fresh && (k <= ON.k || k >= courseOf()[2])) return;
if (fresh) {
ON.m = m; ON.course = c;
for (let i = 0; i < NSEAT; i++) { ON.inM[i] = !!((on >> i) & 1); ON.gone[i] = !!((g >> i) & 1); ON.sc[i].fill(-1); ON.tot[i] = 0; ON.tagN[i] = -1; }
ON.live = true; ON.res = false; ON.rdy = 0; ON.iWant = false; ON.menu = false; ON.banT = 0;
parts.length = 0; rings.length = 0; pops.length = 0;
tone(440, 0.06, { type: 'triangle' });
tone(660, 0.08, { type: 'triangle', delay: 0.07 });
}
ON.k = k; ON.t0 = t0; ON.dl = t0 + LIMIT_MS; ON.n.fill(0); ON.d.fill(0); ON.rc.fill(0); ON.vv.fill(0);
ON.sentN = -1; ON.sentD = -1; ON.bP = -1; ON.bT = 0; ON.meDirty = false; ON.tu = false;
state = 'playing'; paused = false; clearKeys();
loadHole(COURSES[ON.course][1] + k);
holeT = clamp((hostNow() - t0) / 1000, 0, 5);
