ctx.fillStyle = COL.scrim; ctx.fillRect(0, HUD + 16, W, H - HUD - 16);
const pw = 780, ph = 356, px = (W - pw) / 2, py = HUD + 16 + (H - HUD - 16 - ph) / 2, s = ON.sc[ON.me][ON.k];
