ctx.fillStyle = COL.hi; ctx.beginPath(); rrect(ctx, px + 40, py + 296, Math.max(6, (pw - 80) * q), 6, 3); ctx.fill();
tx('Next: ' + (next ? next.name : ''), W / 2, py + 330, '600 15px ' + FB, COL.body);
