function defaultSave() {
const up = {};
for (let i = 0; i < UP.length; i++) up[UP[i].id] = 0;
return { v: 1, scrap: 0, up: up, wagons: 2, maxLvl: 0, bestEnd: 0, hints: 0, runs: 0, kills: 0, wins: 0 };
}
function int(v, lo, hi, def) {
const n = +v;
return Number.isFinite(n) ? clamp(Math.round(n), lo, hi) : def;
}
function sanitizeSave(o) {
const d = defaultSave();
if (!o || typeof o !== 'object') return d;
d.scrap = int(o.scrap, 0, 1e9, 0);
if (o.up && typeof o.up === 'object') for (let i = 0; i < UP.length; i++) d.up[UP[i].id] = int(o.up[UP[i].id], 0, UP[i].max, 0);
d.wagons = int(o.wagons, 2, 4, 2);
d.maxLvl = int(o.maxLvl, 0, LEVELS.length - 1, 0);
d.bestEnd = int(o.bestEnd, 0, 1e6, 0);
d.hints = int(o.hints, 0, 1 << 20, 0);
d.runs = int(o.runs, 0, 1e7, 0);
d.kills = int(o.kills, 0, 1e10, 0);
d.wins = int(o.wins, 0, 1e6, 0);
return d;
}

