deco(.15,.1,dd,x-w/2-.07,.05,z,0x1a1210);deco(.15,.1,dd,x+w/2+.07,.05,z,0x1a1210);
L.hazards.push({t:'molt',name:'SLAG',x0:x-w/2,z0:z-dd/2,x1:x+w/2,z1:z+dd/2,cx:x,cz:z,h:.6});
