let bolts=[];
for(let i=0;i<MAX_BOLT;i++)bolts.push({on:false,x:0,y:0,z:0,vx:0,vy:0,vz:0,t:0,dmg:0,r:.3,col:new THREE.Color(),lob:false,aoe:0,size:.12});
