if(e.stT<=0){e.st='atk';e.stT=.9;e.burst=0;_v1.set(P.pos.x-e.pos.x,P.pos.y+.9-e.pos.y,P.pos.z-e.pos.z).normalize().multiplyScalar(13);e.vel.copy(_v1);sfx('Pounce')}
