a2:{dur:.3,h0:.05,h1:.17,reach:2.7,cos:.1,dmg:11,cut:'mid',pose:1,a0:1.2,a1:-1.5,air:1,next:'a1',name:'AIR RIP'},
down:{dur:1.4,h0:0,h1:1.4,reach:3.2,cos:-1,dmg:30,cut:'high',pose:6,plunge:1,name:'DOWNRIP'},
