_v1.subVectors(B.lineB,B.lineA);let len=_v1.length()||1;_v1.multiplyScalar(1/len);
let px=P.pos.x-B.lineA.x,pz=P.pos.z-B.lineA.z,along=clamp(px*_v1.x+pz*_v1.z,0,len),off=M.abs(px*_v1.z-pz*_v1.x);
