amb = null;
for (let i = 0; i < A.srcs.length; i++) { try { A.srcs[i].stop(); } catch (e) { /* already stopped */ } }
for (let i = 0; i < A.nodes.length; i++) { try { A.nodes[i].disconnect(); } catch (e) { /* ignore */ } }
