function standings() {
const rows = [{ name: 'You #' + save.num, pts: save.career.pts[0], me: true }];
for (let i = 0; i < 11; i++) { const r = save.career.roster[i]; rows.push({ name: '#' + r.num + ' ' + r.name, pts: save.career.pts[i + 1], me: false }); }
rows.sort(function (a, b) { return b.pts - a.pts || (a.me ? -1 : b.me ? 1 : 0); });
return rows;
}
