hctx.setTransform(dpr * hudK, 0, 0, dpr * hudK, 0, 0);
btnN = 0;
if (flashA > 0) { hctx.fillStyle = 'rgba(255,248,230,' + flashA.toFixed(3) + ')'; hctx.fillRect(0, 0, VW, VH); }
if (slowT > 0) {
const g = hctx.createRadialGradient(VW / 2, VH / 2, VH * 0.3, VW / 2, VH / 2, VH * 0.85);
g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(10,6,4,0.45)');
hctx.fillStyle = g; hctx.fillRect(0, 0, VW, VH);
}
