const f = H.ph === 2 ? 0.7 + Math.random() * 0.3 : H.ph === 1 ? (animT * 8 % 1 < 0.5 ? 0.3 : 0.05) : 0.03;
H.mat.color.setRGB(0.42 * f, 0.94 * f, f);
if (H.ph === 2 && Math.random() < dt * 14) sparkAt(H.x0 + Math.random() * (H.x1 - H.x0), 0.1, H.z0 + Math.random() * (H.z1 - H.z0), 3, 0x9cf0ff, 4);
