function hzX(sg, x0, k) { const c = sg.hz[k], n = sg.hz.length; return c === 'P' ? x0 + SEG_W * (n > 1 ? (k ? 0.72 : 0.3) : 0.5) : c === 'E' ? x0 + SEG_W * 0.62 : x0 + SEG_W * 0.42; }
