const TITLE_ITEMS = NET_SHOW ? ['STORY', 'FIGHTER', 'SURVIVAL', 'BOSS RUSH', 'GARAGE', 'ONLINE'] : ['STORY', 'FIGHTER', 'SURVIVAL', 'BOSS RUSH', 'GARAGE'];
