car.mode = 'ground'; car.pc = best; car.s = bs; car.u = clamp(bu, -(best.def.pipe ? LIM_PIPE : LIM_FLAT), best.def.pipe ? LIM_PIPE : LIM_FLAT);
car.a = a; car.vt = vt; car.vl = vl; car.airT = 0; car.offT = 0; car.landT = 0.25;
updateGroundPose();
if (impact > 6 && align >= 0.35) {
noise(0.12, { filter: 500, vol: Math.min(0.25, 0.05 + impact * 0.008) });
if (impact > 18) addShake(0.2);
for (let k = 0; k < 12; k++) {
const ang = k / 12 * TAU;
emit(car.pos.x, car.pos.y - 0.4, car.pos.z, Math.cos(ang) * 6, 1.5, Math.sin(ang) * 6, 0.45, 0.8, 0.65, 0.75, 2);
}
}
