let state = 'title';      // title | select | race | over | editor
let paused = false, menuSel = 0, selTrack = 0, camMode = 0, animT = 0, overAt = 0, acc = 0, camSnap = true;
let touchMode = !!api.isTouch, orbitA = 0.6, fov = 72, toastMsg = '', toastCol = UI.body, toastT = 0;
let engineSndT = 0;
