const touches = new Map();
try { camMode = api.load('cam') === '1' ? 1 : 0; } catch (e) { camMode = 0; }
for (let i = 0; i < CAMPAIGN.length; i++) {
if (!unlocked(i)) break;
selTrack = i;
if (!pbs[i] || medalFor(i, pbs[i].t) < 3) break;
}

