const t = (ed.lvl * LVL - camera.position.y) / tv1.y;
if (!(t > 0)) return false;
pick.x = clamp(Math.round((camera.position.x + tv1.x * t) / TILE), -GRID, GRID);
pick.z = clamp(Math.round((camera.position.z + tv1.z * t) / TILE), -GRID, GRID);
