drawMedal(c, cx + 30, y + 2, 9, med);
txt(c, MEDAL_NAME[med], cx + 50, y, 15, FONT_B, got ? UI.head : UI.body, 'left', 100, '700');
txt(c, fmtTime(tr.t[m]), cx + cw - 46, y, 15, FONT_M, got ? UI.ok : UI.body, 'right', 120, '600');
