m.position.set(D[A + 1] + (D[B + 1] - D[A + 1]) * f, D[A + 2] + (D[B + 2] - D[A + 2]) * f, D[A + 3] + (D[B + 3] - D[A + 3]) * f);
nq.set(D[A + 4], D[A + 5], D[A + 6], D[A + 7]).normalize();
