function coursePar(def) {
let t = 0;
for (let i = 0; i < def.ops.length; i++) {
const o = def.ops[i], k = o[0];
if (k === 'R') {
t += o[1] / 9.0;
const f = o[3] || [];
for (let j = 0; j < f.length; j++) {
const fk = f[j][0];
if (fk === 'low') t += 0.05;
else if (fk === 'block') t += (f[j][3] || 1) > 1.3 ? 0.35 : 0.1;
else if (fk === 'pad') t -= 0.35;
else if (fk === 'fin') t -= Math.max(0, (o[1] - f[j][1]) / 9.0);
}
} else if (k === 'RS') t += o[1] / 12.5;
else if (k === 'RT') t += o[1] / 8.0;
else if (k === 'G') t += o[1] / (o[1] >= 7 ? 12.5 : 9.5) + (o[2] >= 1.25 ? 0.35 : 0);
else if (k === 'GW') t += o[1] / 10;
else if (k === 'GWW') t += o[1] / 9.5;
else if (k === 'GZ') t += (o[1] + 7) / 13;
else if (k === 'GS') t += o[1] / 8.5;
}
return Math.max(10, t - 3 / 9.0); // the run starts 3 m into the first roof
}
function halfUp(t) { return Math.ceil(t * 2) / 2; }
for (let i = 0; i < COURSES.length; i++) {
const p = coursePar(COURSES[i]);
COURSES[i].medals = [halfUp(p * 1.7), halfUp(p * 1.32), halfUp(p * 1.12), halfUp(p * 1.0)];
}
function medalFor(ci, t) {
if (!(t > 0)) return -1;
const m = COURSES[ci].medals;
let best = -1;
for (let k = 0; k < 4; k++) if (t <= m[k] + 1e-6) best = k;
return best;
}

