if (!kind) { g.fillStyle = 'rgba(255,255,255,0.18)'; g.fillRect(x + 7, y + 8, 20, 4); }
g.fillStyle = kind ? 'rgba(0,0,0,0.3)' : 'rgba(40,30,40,0.25)'; g.fillRect(x + 16, y + 8, 2, 18);
