let mode = 'title', paused = false, settingsOpen = false, settingsSel = 0, destroyed = false;
let overAt = 0, uiT = 0, acc = 0;
let selCourse = 0;
for (let i = 0; i < COURSES.length; i++) if (unlocked(i)) selCourse = i;
for (let i = 0; i < COURSES.length; i++) if (unlocked(i) && medalFor(i, records[i].t) < 2) { selCourse = i; break; }
let titleBuildT = 0;                  // debounce for rebuilding the backdrop course on the title
let runT = 0, runStarted = false, cpNext = 0;
const splits = new Float64Array(48);
const splitShow = { i: 0, t: 0, d: 0, has: false, at: -10 };
const hintSeen = new Uint8Array(32);
