runT = 0; runStarted = false; recN = 0; cpNext = 0;
for (let i = 0; i < cps.length; i++) cps[i].mesh.material = i === 0 ? mats.cpNext : mats.cpIdle;
for (let i = 0; i < splits.length; i++) splits[i] = 0;
