pl.fade = 0; pl.fadeT = 0; pl.fadeMoved = false;
respawnAt(-1);
clearParticles();
stick = null; lookPtr = null; drag = null; jumpPtr = null; slidePtr = null; lookDX = 0; lookDY = 0;
slideWant = !!(keys.ShiftLeft || keys.ShiftRight || keys.KeyC);
