const rec = records[courseIdx];
const has = !!(rec.s && rec.s.length === cps.length);
splitShow.i = i; splitShow.t = runT; splitShow.has = has; splitShow.d = has ? runT - rec.s[i] : 0; splitShow.at = uiT;
cps[i].mesh.material = mats.cpDone;
cpNext = i + 1;
if (cpNext < cps.length) cps[cpNext].mesh.material = mats.cpNext;
emit(cps[i].sx, cps[i].sy + 1.5, cps[i].sz, 26, has && splitShow.d > 0 ? 0xff7a7a : 0x6effc0, 4, 2.5, 0.7, 2.5);
