const career = { day: 1, money: 0, total: 0, upg: { armour: 0, engine: 0, tyres: 0, anchor: 0, probes: 0, radar: 0, launcher: 0 } };
function resetCareer() {
career.day = 1; career.money = 0; career.total = 0;
for (let i = 0; i < UPG.length; i++) career.upg[UPG[i].key] = 0;
}
function loadCareer() {
let raw = null;
try { raw = typeof api.load === 'function' ? api.load('career') : null; } catch (e) { raw = null; }
if (typeof raw !== 'string' || !raw) return;
try {
const o = JSON.parse(raw);
if (!o || typeof o !== 'object') return;
career.day = clampInt(o.day, 1, 99999, 1);
career.money = clampInt(o.money, 0, 1e12, 0);
career.total = clampInt(o.total, 0, 1e13, 0);
const u = o.upg && typeof o.upg === 'object' ? o.upg : {};
for (let i = 0; i < UPG.length; i++) career.upg[UPG[i].key] = clampInt(u[UPG[i].key], 0, UPG[i].max, 0);
} catch (e) { resetCareer(); }
}
