const wf = ctx.createBiquadFilter(); wf.type = 'bandpass'; wf.frequency.value = 400; wf.Q.value = 0.7;
const wg = ctx.createGain(); wg.gain.value = 0;
ws.connect(wf); wf.connect(wg); wg.connect(hA.out);
const rs = ctx.createBufferSource(); rs.buffer = noiseBuf; rs.loop = true; rs.playbackRate.value = 0.6;
const rf = ctx.createBiquadFilter(); rf.type = 'lowpass'; rf.frequency.value = 160; rf.Q.value = 0.9;
const rg = ctx.createGain(); rg.gain.value = 0;
rs.connect(rf); rf.connect(rg); rg.connect(hA.out);
const ns = ctx.createBufferSource(); ns.buffer = noiseBuf; ns.loop = true;
const nf = ctx.createBiquadFilter(); nf.type = 'highpass'; nf.frequency.value = 2200;
const ng = ctx.createGain(); ng.gain.value = 0;
ns.connect(nf); nf.connect(ng); ng.connect(hA.out);
