const TB = [
{ id: 'left', x: 0, y: 0, r: 50, label: '' }, { id: 'right', x: 0, y: 0, r: 50, label: '' },
{ id: 'turbo', x: 0, y: 0, r: 36, label: 'TURBO' }, { id: 'gas', x: 0, y: 0, r: 58, label: 'GAS' },
{ id: 'brake', x: 0, y: 0, r: 42, label: 'BRAKE' }, { id: 'anchor', x: 0, y: 0, r: 44, label: 'ANCHOR' },
{ id: 'probe', x: 0, y: 0, r: 44, label: 'PROBE' }, { id: 'cam', x: 0, y: 0, r: 22, label: 'CAM' },
{ id: 'flip', x: 0, y: 0, r: 22, label: 'FLIP' }, { id: 'pause', x: 0, y: 0, r: 22, label: 'II' },
];
function layoutTouch() {
const P = {
left: [72, VH - 84], right: [190, VH - 84], turbo: [300, VH - 62], gas: [VW - 82, VH - 98], brake: [VW - 200, VH - 64],
anchor: [VW - 210, VH - 172], probe: [VW - 88, VH - 226], cam: [40, 306], flip: [98, 306], pause: [156, 306],
};
for (let i = 0; i < TB.length; i++) { const p = P[TB[i].id]; TB[i].x = p[0]; TB[i].y = p[1]; }
}
function hitTouch(x, y) {
for (let i = 0; i < TB.length; i++) {
const b = TB[i], dx = x - b.x, dy = y - b.y, rr = b.r + 10;
if (dx * dx + dy * dy <= rr * rr) return b.id;
}
return null;
}
function touchHeld(id) {
return id === 'left' ? tIn.left : id === 'right' ? tIn.right : id === 'gas' ? tIn.gas : id === 'brake' ? tIn.brake :
id === 'anchor' ? tIn.anchor : id === 'turbo' ? tIn.turbo : false;
}
function drawTouch(ctx) {
for (let i = 0; i < TB.length; i++) {
const b = TB[i], on = touchHeld(b.id);
ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, TAU);
ctx.fillStyle = on ? 'rgba(255,201,60,0.38)' : 'rgba(16,22,38,0.5)'; ctx.fill();
ctx.lineWidth = 2; ctx.strokeStyle = on ? UI.hi : 'rgba(255,255,255,0.28)'; ctx.stroke();
if (b.id === 'left' || b.id === 'right') {
const s = b.id === 'left' ? -1 : 1;
ctx.beginPath(); ctx.moveTo(b.x + s * 16, b.y); ctx.lineTo(b.x - s * 10, b.y - 16); ctx.lineTo(b.x - s * 10, b.y + 16); ctx.closePath();
ctx.fillStyle = 'rgba(255,255,255,0.85)'; ctx.fill();
} else {
const col = b.id === 'anchor' && T.anchored ? UI.hi : b.id === 'probe' && T.probes <= 0 ? UI.dim : UI.head;
txt(ctx, b.label, b.x, b.y + 1, b.r > 30 ? 13 : 11, FONT_B, col, 'center', b.r * 1.8, '800');
}
}
if (T.probes > 0) txt(ctx, 'x' + T.probes, TB[6].x + 34, TB[6].y - 34, 13, FONT_M, UI.hi, 'center', 0, '700');
}

