txt(ctx, fmtClock(left), VW - 234, 55, 24, FONT_M, left < 30 ? UI.danger : UI.head, 'left', 0, '700');
txt(ctx, 'DAY ' + career.day, VW - 24, 30, 12, FONT_M, UI.hi, 'right');
