const order = new Int8Array(MAX_TANKS);
function drawEndPanel() {
anchor(0.5, 0.5);
const a = Math.min(1, (phaseT - 0.9) / 0.4);
if (a <= 0) return;
ctx.globalAlpha = a;
panel(ctx, 230, 104, 500, 404);
const R = roundResult;
const head = R === 'win' ? (rcfg.mode === 'surv' ? 'ARENA HELD' : 'ROUND WON') : R === 'draw' ? 'TIME UP: DRAW' : (player.alive ? 'ROUND LOST' : 'DESTROYED');
txt(ctx, head, 480, 146, 36, FONT_D, R === 'win' ? UI.ok : R === 'draw' ? UI.hi : UI.danger, 'center', 440);
txt(ctx, 'Round ' + rcfg.round + '  ·  ' + MAPS[rcfg.map].name + '  ·  ' + MODE_NAMES[rcfg.mode], 480, 178, 14, FONT_B, UI.body, 'center', 440, '700');
txt(ctx, '+' + fmtInt(roundPts) + ' score     +' + fmtInt(roundScrap) + ' scrap' + (flawlessGot ? '     FLAWLESS' : ''), 480, 208, 16, FONT_M, UI.hi, 'center', 440, '800');
let n = 0;
for (let i = 0; i < MAX_TANKS; i++) if (tanks[i].active && (tanks[i].isPlayer || tanks[i].kills > 0 || tanks[i].dmgDealt > 0 || rcfg.mode !== 'surv')) order[n++] = i;
for (let i = 1; i < n; i++) { // insertion sort: team, then kills
const v = order[i], tv = tanks[v];
let j = i - 1;
while (j >= 0) {
const tj = tanks[order[j]];
const before = tj.team > tv.team || (tj.team === tv.team && tj.kills < tv.kills);
if (!before) break;
order[j + 1] = order[j]; j--;
}
order[j + 1] = v;
}
txt(ctx, 'TANK', 262, 238, 11, FONT_B, UI.dim, 'left', 0, '800');
txt(ctx, 'KILLS', 600, 238, 11, FONT_B, UI.dim, 'right', 0, '800');
txt(ctx, 'DAMAGE', 698, 238, 11, FONT_B, UI.dim, 'right', 0, '800');
for (let r = 0; r < Math.min(n, 8); r++) {
const t = tanks[order[r]], y = 260 + r * 24;
if (t.isPlayer) { ctx.fillStyle = 'rgba(255, 201, 60, 0.1)'; ctx.fillRect(250, y - 11, 460, 22); }
ctx.fillStyle = teamCss(t); ctx.fillRect(254, y - 5, 4, 10);
txt(ctx, t.name + (t.alive ? '' : '  ✕'), 266, y, 14, FONT_B, t.alive ? '#FFFFFF' : UI.dim, 'left', 290, '700');
txt(ctx, String(t.kills), 600, y, 14, FONT_M, '#FFFFFF', 'right', 0, '700');
txt(ctx, String(Math.round(t.dmgDealt)), 698, y, 14, FONT_M, UI.body, 'right', 0, '700');
}
if (phaseT > 1.4 && blinkOn()) {
const last = run && (!run.campaign || run.lives <= 0);
txt(ctx, (touchUI ? 'Tap' : 'Press Space') + (last ? ' to see results' : ' to continue to the garage'), 480, 480, 17, FONT_B, UI.hi, 'center', 440, '800');
}
ctx.globalAlpha = 1;
}
