function cycleIndex(cur, n, dir, flags) {
for (let k = 1; k <= n; k++) { const v = ((cur + dir * k) % n + n) % n; if (!flags || flags[v]) return v; }
return cur;
}
function toggleAim() {
prof.aim = prof.aim ? 0 : 1; aimSrc = prof.aim; saveProfile();
popup('Turret aim: ' + (prof.aim === 0 ? 'mouse / trackpad pointer' : 'keys (arrows or J / L)'), UI.body);
}
function adjust(id, dir) {
switch (id) {
case 'q_map': quick.map = cycleIndex(quick.map, MAPS.length, dir, null); break;
case 'q_mode': quick.mode = cycleIndex(quick.mode, 3, dir, null); break;
case 'q_bots': if (quick.mode !== 0) { sfx('deny'); return; } quick.bots = clamp(quick.bots + dir, 1, 5); break;
case 'q_diff': quick.diff = cycleIndex(quick.diff, 3, dir, null); break;
case 'q_ch': quick.ch = cycleIndex(quick.ch, 3, dir, prof.ch); break;
case 'q_paint': quick.paint = cycleIndex(quick.paint, PAINTS.length, dir, prof.paints); break;
case 'q_spec': quick.special = cycleIndex(quick.special, QSPECIAL.length, dir, null); break;
case 's_aim': prof.aim = prof.aim ? 0 : 1; aimSrc = prof.aim; saveProfile(); break;
case 's_shake': prof.shake = !prof.shake; if (!prof.shake) shake = 0; saveProfile(); break;
case 's_cam': prof.camFar = !prof.camFar; saveProfile(); break;
case 'n_map': case 'n_mode': case 'n_bots':
if (!net || !net.host) return;
if (id === 'n_map') ncfg.map = cycleIndex(ncfg.map, MAPS.length, dir, null);
else if (id === 'n_mode') ncfg.md = 1 - ncfg.md;
else ncfg.bots = clamp(ncfg.bots + dir, 0, MAX_TANKS - net.hum);
netCfg(); break;
case 'n_ch': npick.ch = cycleIndex(npick.ch, 3, dir, prof.ch); netPick(); break;
case 'n_pt': npick.pt = cycleIndex(npick.pt, PAINTS.length, dir, prof.paints); netPick(); break;
case 'n_sp': npick.sp = cycleIndex(npick.sp, QSPECIAL.length, dir, null); netPick(); break;
default: return;
}
sfx('ui');
}
