function netStep(dt) { // fixed step of an online battle
phaseT += dt;
const intro = phase === 'intro';
if (!intro && phase !== 'battle') return;
if (!intro) { roundT += dt; timeLeft = Math.max(0, timeLeft - dt); }
playerInput(dt);
if (netMenu || intro) { player.throttle = 0; player.turn = 0; player.firing = false; player.mg = false; player.boosting = false; }
for (let i = 0; i < MAX_TANKS; i++) {
const t = tanks[i];
if (!t.active) continue;
if (t.net) { netTankStep(t, dt); continue; }
if (i > 0 && t.alive) {
if (intro) { t.throttle = 0; t.turn = 0; t.firing = false; t.mg = false; t.boosting = false; t.aimYaw = t.yaw; }
else aiStep(t, dt);
}
tankStep(t, dt);
}
if (intro) {
if (phaseT < 3 && Math.floor(phaseT) !== Math.floor(phaseT - dt)) sfx('count');
if (phaseT >= 3) { phase = 'battle'; phaseT = 0; sfx('go'); }
return;
}
collideTanks();
updShells(dt); updBullets(dt); updDrones(dt); updMines(dt); updKits(dt); updZones(dt); updFalling(dt);
updSpotting(dt);
if (NH) {
updBlasts(dt);
for (let i = 0; i < MAX_TANKS; i++) {
const t = tanks[i];
if (t.active && !t.alive && t.respT > 0) { t.respT -= dt; if (t.respT <= 0) netRespawn(t); }
}
if (timeLeft <= 0) netEnd();
} else if (timeLeft <= 0) { net.endWait += dt; if (net.endWait > 6) netResults(null, null); } // the host's result never came
}
function netPre(dt) {
const now = performance.now();
if (!net.host && now - net.lastRx > (netLive ? 10000 : 30000)) { netLeave('Connection lost'); return; }
if (!netLive) return;
for (let i = 0; i < MAX_TANKS; i++) { const t = tanks[i]; if (t.net && t.active && t.alive) netPose(t, now - 100, dt); }
}
function netPost(dt) {
net.sendT += dt;
const tick = net.sendT >= 0.05;
if (tick) net.sendT = Math.min(0.05, net.sendT - 0.05);
if (!netLive) {
net.plT -= dt; if (net.plT <= 0) { net.plT = 0.5; netPlayers(); }
if (net.host) { net.cfgT -= dt; if (net.cfgT <= 0) { net.cfgT = 2; netCfg(); } } // also a keep-alive for the guests
return;
}
if (NG) {
if (!tick) return;
if (net.mgPend > 0) netMgFlush();
const t = player;
nsend({ t: 'p', b: net.bid, q: ++net.sq, l: t.life,
a: [Math.round(t.x * 100), Math.round(t.z * 100), Math.round(t.yaw * 1000), Math.round(t.tyaw * 1000), Math.round(t.pitch * 1000), t.boostOn ? 1 : 0] }, FAST);
return;
}
const now = performance.now();
for (let g = 1; g < MAX_TANKS; g++) { // a silent player is driven by a bot
const t = tanks[g];
if (t.net && t.human && now - net.rx[g] > 4000) { t.net = 0; t.ai.pathN = 0; t.ai.state = 0; t.ai.target = -1; }
}
net.sumT += dt;
if (net.sumT >= 3) { net.sumT = 0; net.k = rowHashes(); }
if (tick) netSnapshot();
netFlush();
}

