if (ride && !started && (gas || brk || leanT)) started = true;
if (parked && (!ride || gas || brk || leanT)) parked = false;
leanCur += clamp(leanT - leanCur, -8 * STEP, 8 * STEP);
for (let sub = 0; sub < SUBS; sub++) {
worldT += HS;
moveBodies(HS);
if (phase !== PH_FELL && !parked) bikeSub(HS, gas, brk, leanCur, ride);
}
