const bs = T.bodies;
for (let i = 0; i < bs.length; i++) {
const b = bs[i];
if (b.hitT > 0) b.hitT -= STEP;
if (b.type === BT_BOOM && b.alive && b.fuse >= 0) { b.fuse -= STEP; if (b.fuse <= 0) explode(b); }
}
