for (let i = 0; i < pl.length; i++) {
const p = pl[i];
if (p.st === 1) { p.t += STEP; if (p.t > 0.45) { p.st = 2; grpOn[p.g] = 0; p.vy = 0; } }
else if (p.st === 2) { p.vy += GRAV * STEP; p.oy += p.vy * STEP; p.rot += p.rs * STEP; if (p.oy > 1400) p.st = 3; }
}
