function blink() { return 0.55 + 0.45 * Math.sin(menuT * 5 + overT * 5); }
function safeBest() { try { const b = api.best(); return typeof b === 'number' && isFinite(b) ? b : null; } catch (e) { return null; } }

function hillY(x) { return 500 + 16 * Math.sin(x * 0.011 + 1.2) + 9 * Math.sin(x * 0.027 + 0.4); }
function drawMenuBackdrop(wi, showBike) {
camRefY = 0;
drawBackdrop(menuT * 50, 0, wi);
const wd = WORLDS[wi];
ctx.beginPath(); ctx.moveTo(0, H);
for (let x = 0; x <= W; x += 24) ctx.lineTo(x, hillY(x));
ctx.lineTo(W, H); ctx.closePath();
ctx.fillStyle = wd.ground; ctx.fill();
ctx.beginPath(); ctx.moveTo(0, hillY(0));
for (let x = 24; x <= W; x += 24) ctx.lineTo(x, hillY(x));
ctx.lineWidth = 3; ctx.strokeStyle = wd.edge; ctx.stroke();
if (showBike) {
const bx = 250, gy = hillY(bx), a = -0.06 - 0.16 * (0.5 + 0.5 * Math.sin(menuT * 1.7));
poseRest(MP, bx + 26 * Math.sin(a), gy - 41 + (a + 0.06) * -30, a, -0.5);
MP.ry = Math.min(MP.ry, hillY(MP.rx) - WR); MP.fy = Math.min(MP.fy, hillY(MP.fx) - WR);
MP.bc = BIKE_COLS[save.bc]; MP.rc = RIDER_COLS[save.rc]; MP.sr = menuT * 9; MP.sf = menuT * 9; MP.rider = true; MP.ghost = false;
drawBikeArt(ctx, MP);
}
}

const TITLE_BTNS = NET ? [[262, 360, 132, 40, 'TRACKS  (T)', 'TRACKS'], [414, 360, 132, 40, 'GARAGE  (G)', 'GARAGE'], [566, 360, 132, 40, 'ONLINE  (O)', 'ONLINE']]
: [[338, 360, 132, 40, 'TRACKS  (T)', 'TRACKS'], [490, 360, 132, 40, 'GARAGE  (G)', 'GARAGE']];
let titleNext = '', titleBestStr = '';
function openTitle() {
state = 'title'; paused = false;
const n = nextTrackIdx();
titleNext = 'Next up: ' + (Math.floor(n / 6) + 1) + '-' + (n % 6 + 1) + '  ' + TRACKS[n].n;
const b = safeBest();
titleBestStr = b !== null ? 'Best: ' + b + ' medal points' : '';
engineStop();
}
function drawTitle() {
drawMenuBackdrop(0, true);
ctx.fillStyle = 'rgba(8,12,22,0.35)'; ctx.fillRect(0, 0, W, H);
ctx.textAlign = 'center';
ctx.font = F_D72;
ctx.lineWidth = 8; ctx.strokeStyle = 'rgba(10,6,16,0.85)'; ctx.lineJoin = 'round';
ctx.strokeText('TRIAL BURN', W / 2, 160);
ctx.fillStyle = logoGrad; ctx.fillText('TRIAL BURN', W / 2, 160);
ctx.font = F_S18; ctx.fillStyle = COL.head;
ctx.fillText('Physics dirt-bike trials. Throttle, brake and lean over brutal courses.', W / 2, 212);
ctx.font = F_B16; ctx.fillStyle = COL.body;
ctx.fillText('Finish fast with few faults to win medals, unlock worlds and new bikes.', W / 2, 240);
ctx.globalAlpha = blink(); ctx.font = F_S18; ctx.fillStyle = COL.hi;
ctx.fillText(touchUI ? 'Tap to start' : 'Press Space to start', W / 2, 304);
ctx.globalAlpha = 1;
ctx.font = F_B14; ctx.fillStyle = COL.body; ctx.fillText(titleNext, W / 2, 332);
for (let i = 0; i < TITLE_BTNS.length; i++) { const b = TITLE_BTNS[i]; pill(b[0], b[1], b[2], b[3], touchUI ? b[5] : b[4], false, i < 2 || NET.supported); }
if (NET && !NET.supported) { ctx.font = F_B13; ctx.fillStyle = COL.dim; ctx.textAlign = 'center'; ctx.fillText('Online play needs WebRTC, which this browser does not have.', W / 2, 414); }
if (titleBestStr) { ctx.font = F_M14; ctx.fillStyle = COL.hi; ctx.textAlign = 'center'; ctx.fillText(titleBestStr, W / 2, 430); }
ctx.font = F_B13; ctx.fillStyle = COL.body;
ctx.fillText(touchUI ? 'GAS / BRAKE on the right, LEAN BACK / LEAN FWD on the left' : 'W / Up throttle  \u00B7  S / Down brake  \u00B7  A D lean  \u00B7  R checkpoint  \u00B7  Esc pause' + (NET ? '  \u00B7  O online' : ''), W / 2, 584);
}
function titleClick(x, y) {
if (inRect(TITLE_BTNS[0], x, y)) { openSelect(); return; }
if (inRect(TITLE_BTNS[1], x, y)) { openGarage('title'); return; }
if (NET && inRect(TITLE_BTNS[2], x, y)) { if (NET.supported) openOnline(); return; }
startTrack(nextTrackIdx());
}

const SEL_X0 = 59, SEL_Y0 = 92, SEL_CW = 132, SEL_CH = 60, SEL_PITCH_X = 142, SEL_PITCH_Y = 84;
const SEL_BACK = [20, 22, 100, 34], SEL_GAR = [840, 22, 100, 34];
let selInfo = [], selPts = '';
const selRows = ['', '', '', '', ''];
function openSelect() {
state = 'select'; paused = false;
selInfo = [];
ctx.font = F_S14;
for (let i = 0; i < NT; i++) selInfo.push({ label: (Math.floor(i / 6) + 1) + '-' + (i % 6 + 1), name: TRACKS[i].n, best: save.tBest[i] ? fmtTime(save.tBest[i]) : '--:--.--', open: trackOpen(i), small: ctx.measureText(TRACKS[i].n).width > SEL_CW - 22 });
selPts = 'Medal points ' + totalPts() + ' / ' + (NT * 4);
for (let w = 0; w < 5; w++) selRows[w] = WORLDS[w].name.toUpperCase() + (worldOpen(w) ? '' : '   \u00B7   LOCKED, NEEDS ' + WORLD_REQ[w] + ' MEDAL POINTS');
if (!trackOpen(selIdx)) selIdx = nextTrackIdx();
engineStop();
buildSelDetail();
}
let selLine1 = '', selLine2 = '', selLock = '';
function buildSelDetail() {
const i = selIdx, t = TRACKS[i], w = Math.floor(i / 6);
selLine1 = selInfo[i].label + '  ' + t.n.toUpperCase() + '   \u00B7   ' + WORLDS[w].name;
const g = save.medal[i] >= 3;
selLine2 = 'Silver ' + fmtSec(t.s) + ' (\u2264 3 faults)   Gold ' + fmtSec(t.g) + ' (\u2264 1 fault)   Platinum ' + (g ? fmtSec(t.p) + ' (no faults)' : '???') + '   Best ' + selInfo[i].best;
selLock = '';
if (!worldOpen(w)) selLock = 'Locked: ' + WORLDS[w].name + ' opens at ' + WORLD_REQ[w] + ' medal points (you have ' + totalPts() + ').';
else if (!trackOpen(i)) selLock = 'Locked: earn any medal on ' + selInfo[i - 1].label + ' ' + TRACKS[i - 1].n + ' first.';
}
const CELL_R = [0, 0, SEL_CW, SEL_CH];
function cellRect(i) { CELL_R[0] = SEL_X0 + (i % 6) * SEL_PITCH_X; CELL_R[1] = SEL_Y0 + Math.floor(i / 6) * SEL_PITCH_Y + 16; return CELL_R; }
function drawSelect() {
drawMenuBackdrop(Math.floor(selIdx / 6), false);
ctx.fillStyle = 'rgba(8,12,22,0.62)'; ctx.fillRect(0, 0, W, H);
ctx.textAlign = 'center'; ctx.font = F_D34; ctx.fillStyle = COL.head; ctx.fillText('SELECT TRACK', W / 2, 56);
ctx.font = F_M12; ctx.fillStyle = COL.hi; ctx.fillText(selPts, W / 2, 78);
pill(SEL_BACK[0], SEL_BACK[1], SEL_BACK[2], SEL_BACK[3], '\u2190 BACK', false, true);
pill(SEL_GAR[0], SEL_GAR[1], SEL_GAR[2], SEL_GAR[3], 'GARAGE', false, true);
for (let w = 0; w < 5; w++) {
const y = SEL_Y0 + w * SEL_PITCH_Y + 10;
ctx.textAlign = 'left'; ctx.font = F_L11;
ctx.fillStyle = worldOpen(w) ? WORLDS[w].accent : COL.dim;
ctx.fillText(selRows[w], SEL_X0, y);
}
for (let i = 0; i < NT; i++) {
const r = cellRect(i), inf = selInfo[i], sel = i === selIdx;
ctx.beginPath(); rrect(ctx, r[0], r[1], r[2], r[3], 10);
ctx.fillStyle = inf.open ? 'rgba(16,22,38,0.92)' : 'rgba(16,22,38,0.5)'; ctx.fill();
ctx.lineWidth = sel ? 3 : 1.5; ctx.strokeStyle = sel ? COL.hi : 'rgba(255,255,255,0.12)'; ctx.stroke();
ctx.textAlign = 'left';
ctx.font = F_M12; ctx.fillStyle = COL.dim; ctx.fillText(inf.label, r[0] + 10, r[1] + 17);
ctx.font = inf.small ? F_S12 : F_S14; ctx.fillStyle = inf.open ? COL.head : 'rgba(201,211,227,0.4)'; ctx.fillText(inf.name, r[0] + 10, r[1] + 36);
if (inf.open) { ctx.font = F_M12; ctx.fillStyle = COL.body; ctx.fillText(inf.best, r[0] + 10, r[1] + 53); drawMedal(ctx, r[0] + r[2] - 16, r[1] + 16, 8, save.medal[i]); }
else drawLock(ctx, r[0] + r[2] - 18, r[1] + 18, 0.9);
}
ctx.fillStyle = 'rgba(16,22,38,0.92)'; ctx.beginPath(); rrect(ctx, SEL_X0, 516, 842, 70, 12); ctx.fill();
ctx.textAlign = 'center';
ctx.font = F_S16; ctx.fillStyle = COL.head; ctx.fillText(selLine1, W / 2, 538);
ctx.font = F_B13; ctx.fillStyle = selLock ? COL.danger : COL.body; ctx.fillText(selLock || selLine2, W / 2, 558);
ctx.globalAlpha = blink(); ctx.font = F_S14; ctx.fillStyle = COL.hi;
ctx.fillText(touchUI ? 'Tap a track to ride it' : 'Arrows choose  \u00B7  Space / Enter ride  \u00B7  G garage  \u00B7  Esc back', W / 2, 578);
ctx.globalAlpha = 1;
}
function selectMove(d) {
const col = selIdx % 6, row = Math.floor(selIdx / 6);
let n = selIdx;
if (d === 0) n = col > 0 ? selIdx - 1 : row > 0 ? selIdx - 1 : selIdx;
else if (d === 1) n = col < 5 ? selIdx + 1 : row < 4 ? selIdx + 1 : selIdx;
else if (d === 2) n = row > 0 ? selIdx - 6 : selIdx;
else n = row < 4 ? selIdx + 6 : selIdx;
if (n !== selIdx) { selIdx = n; buildSelDetail(); tone(440, 0.04, { type: 'triangle', vol: 0.07 }); }
}
function selectGo() {
if (trackOpen(selIdx)) { tone(660, 0.07, { type: 'triangle', vol: 0.09 }); startTrack(selIdx); }
else tone(140, 0.12, { type: 'square', vol: 0.07 });
}
function selectClick(x, y) {
if (inRect(SEL_BACK, x, y)) { openTitle(); return; }
if (inRect(SEL_GAR, x, y)) { openGarage('select'); return; }
for (let i = 0; i < NT; i++) {
if (inRect(cellRect(i), x, y)) { selIdx = i; buildSelDetail(); selectGo(); return; }
}
}

const STAT_NAMES = ['POWER', 'GRIP', 'AGILITY', 'TOP SPEED'], GAR_ROW_Y = [100, 300, 370, 458], GAR_ROW_H = [192, 62, 62, 66];
const GAR_L = [492, 138, 40, 44], GAR_R = [868, 138, 40, 44], GAR_DONE = [620, 470, 160, 42];
let garLock = '', garCount = '';
function openGarage(from) {
garFrom = from; state = 'garage'; garRow = 0;
garBike = save.bike;
buildGarLock();
engineStop();
}
function buildGarLock() {
garCount = 'BIKE  ' + (garBike + 1) + ' / ' + BIKES.length;
garLock = bikeOpen(garBike) ? (garBike === save.bike ? 'Equipped' : '') : 'Locked: needs ' + BIKES[garBike].need + ' medal points (you have ' + totalPts() + ')';
}
function garageChange(d) {
if (garRow === 0) {
garBike = (garBike + d + BIKES.length) % BIKES.length;
if (bikeOpen(garBike)) save.bike = garBike;
buildGarLock();
} else if (garRow === 1) save.bc = (save.bc + d + BIKE_COLS.length) % BIKE_COLS.length;
else if (garRow === 2) save.rc = (save.rc + d + RIDER_COLS.length) % RIDER_COLS.length;
tone(520, 0.04, { type: 'triangle', vol: 0.07 });
}
function garageDone() {
persist();
tone(660, 0.07, { type: 'triangle', vol: 0.09 });
if (garFrom === 'select') openSelect(); else openTitle();
}
function drawGarage() {
drawMenuBackdrop(Math.min(4, Math.floor(save.last / 6)), false);
ctx.fillStyle = 'rgba(8,12,22,0.6)'; ctx.fillRect(0, 0, W, H);
ctx.textAlign = 'center'; ctx.font = F_D34; ctx.fillStyle = COL.head; ctx.fillText('GARAGE', W / 2, 56);
panel(ctx, 40, 90, 410, 420);
ctx.fillStyle = 'rgba(255,255,255,0.06)'; ctx.beginPath(); ctx.ellipse(245, 430, 150, 22, 0, 0, TAU); ctx.fill();
ctx.save();
ctx.translate(245, 322); ctx.scale(2.5, 2.5);
poseRest(MP, 0, 0, 0, Math.sin(menuT * 1.5) * 0.25);
MP.bc = BIKE_COLS[save.bc]; MP.rc = RIDER_COLS[save.rc]; MP.sr = menuT * 1.5; MP.sf = menuT * 1.5; MP.rider = true; MP.ghost = false;
if (!bikeOpen(garBike)) ctx.globalAlpha = 0.35;
drawBikeArt(ctx, MP);
ctx.globalAlpha = 1;
ctx.restore();
if (!bikeOpen(garBike)) drawLock(ctx, 245, 250, 2.2);
panel(ctx, 470, 90, 450, 440);
ctx.lineWidth = 2; ctx.strokeStyle = COL.hi;
ctx.beginPath(); rrect(ctx, 480, GAR_ROW_Y[garRow], 430, GAR_ROW_H[garRow], 12); ctx.stroke();
const bt = BIKES[garBike];
ctx.textAlign = 'left'; ctx.font = F_L11; ctx.fillStyle = COL.dim; ctx.fillText(garCount, 496, 122);
pill(GAR_L[0], GAR_L[1], GAR_L[2], GAR_L[3], '\u2039', false, true);
pill(GAR_R[0], GAR_R[1], GAR_R[2], GAR_R[3], '\u203A', false, true);
ctx.textAlign = 'center'; ctx.font = F_D26; ctx.fillStyle = bikeOpen(garBike) ? COL.head : COL.dim; ctx.fillText(bt.name, 700, 170);
ctx.font = F_B14; ctx.fillStyle = COL.body; ctx.fillText(bt.tag, 700, 194);
ctx.font = F_S14; ctx.fillStyle = bikeOpen(garBike) ? COL.ok : COL.danger; ctx.fillText(garLock, 700, 214);
for (let k = 0; k < 4; k++) {
const sv = k === 0 ? bt.torque : k === 1 ? bt.grip : k === 2 ? bt.lean : bt.top;
const y = 232 + k * 16;
ctx.textAlign = 'left'; ctx.font = F_L11; ctx.fillStyle = COL.dim; ctx.fillText(STAT_NAMES[k], 500, y + 8);
ctx.fillStyle = 'rgba(255,255,255,0.1)'; ctx.fillRect(590, y, 300, 8);
ctx.fillStyle = WORLDS[k % 5].accent; ctx.fillRect(590, y, 300 * clamp((sv - 0.6) / 0.85, 0.05, 1), 8);
}
ctx.textAlign = 'left'; ctx.font = F_L11; ctx.fillStyle = COL.dim; ctx.fillText('BIKE COLOUR', 496, 318); ctx.fillText('RIDER COLOUR', 496, 388);
for (let k = 0; k < 6; k++) {
swatch(560 + k * 56, 343, BIKE_COLS[k], k === save.bc);
swatch(560 + k * 56, 413, RIDER_COLS[k], k === save.rc);
}
pill(GAR_DONE[0], GAR_DONE[1], GAR_DONE[2], GAR_DONE[3], 'DONE', garRow === 3, true);
ctx.textAlign = 'center'; ctx.font = F_B13; ctx.fillStyle = COL.body;
ctx.fillText(touchUI ? 'Tap the arrows and colours, then DONE' : 'Up / Down choose a row  \u00B7  Left / Right change  \u00B7  Space or Esc done', W / 2, 562);
}
function swatch(x, y, c, on) {
ctx.fillStyle = c; ctx.beginPath(); ctx.arc(x, y, 16, 0, TAU); ctx.fill();
ctx.lineWidth = on ? 3 : 1.5; ctx.strokeStyle = on ? COL.hi : 'rgba(255,255,255,0.25)';
ctx.beginPath(); ctx.arc(x, y, on ? 21 : 17, 0, TAU); ctx.stroke();
}
function garageClick(x, y) {
if (inRect(GAR_L, x, y)) { garRow = 0; garageChange(-1); return; }
if (inRect(GAR_R, x, y)) { garRow = 0; garageChange(1); return; }
if (inRect(GAR_DONE, x, y)) { garageDone(); return; }
for (let k = 0; k < 6; k++) {
const sx = 560 + k * 56;
if (Math.abs(x - sx) < 24 && Math.abs(y - 343) < 24) { garRow = 1; save.bc = k; tone(520, 0.04, { type: 'triangle', vol: 0.07 }); return; }
if (Math.abs(x - sx) < 24 && Math.abs(y - 413) < 24) { garRow = 2; save.rc = k; tone(520, 0.04, { type: 'triangle', vol: 0.07 }); return; }
}
}

const PAUSE_BTNS = [[241, 300, 112, 40, 'RESUME'], [363, 300, 112, 40, 'CHECKPOINT'], [485, 300, 112, 40, 'RESTART'], [607, 300, 112, 40, 'TRACKS']];
function drawPause() {
ctx.fillStyle = COL.scrim; ctx.fillRect(0, 0, W, H);
panel(ctx, 220, 150, 520, 270);
ctx.textAlign = 'center'; ctx.font = F_D46; ctx.fillStyle = COL.head; ctx.fillText('Paused', W / 2, 220);
ctx.font = F_S18; ctx.fillStyle = COL.hi; ctx.fillText(touchUI ? 'Tap to resume' : 'Press P or click to resume', W / 2, 262);
for (let i = 0; i < 4; i++) { const b = PAUSE_BTNS[i]; pill(b[0], b[1], b[2], b[3], b[4], false, true); }
ctx.font = F_B13; ctx.fillStyle = COL.body; ctx.textAlign = 'center';
ctx.fillText(touchUI ? 'CHECKPOINT costs a fault  \u00B7  RESTART resets the timer' : 'R checkpoint (+1 fault)  \u00B7  Backspace restart  \u00B7  T tracks', W / 2, 378);
ctx.fillText(pauseLine, W / 2, 400);
}
function pauseClick(x, y) {
if (inRect(PAUSE_BTNS[1], x, y)) { paused = false; checkpointRestart(); return; }
if (inRect(PAUSE_BTNS[2], x, y)) { paused = false; startTrack(T.idx); return; }
if (inRect(PAUSE_BTNS[3], x, y)) { paused = false; openSelect(); return; }
paused = false; last = 0;
}
let pauseLine = '';
function setPauseLine() { pauseLine = T ? T.label + '  ' + T.name + '   \u00B7   ' + BIKES[bikeOpen(save.bike) ? save.bike : 0].name : ''; }
function togglePause() {
if (state !== 'playing' || N) return;   // online races never pause
paused = !paused;
if (paused) setPauseLine();
clearInput();
if (paused) engineStop();
last = 0;
tone(paused ? 300 : 460, 0.05, { type: 'triangle', vol: 0.07 });
}

const RES_BTNS = [[246, 444, 150, 42, 'NEXT TRACK'], [405, 444, 150, 42, 'RETRY'], [564, 444, 150, 42, 'TRACKS']];
const RES_ACT_K = ['Press Space to ride the next track', 'Press Space to play again', 'Press Space to pick a track'];
const RES_ACT_T = ['Tap to ride the next track', 'Tap to play again', 'Tap to pick a track'];
function resultsGo(i) {
if (i === 0 && !results.hasNext) i = 1;
tone(660, 0.07, { type: 'triangle', vol: 0.09 });
if (i === 0) { selIdx = T.idx + 1; startTrack(T.idx + 1); }
else if (i === 1) startTrack(T.idx);
else { selIdx = T.idx; openSelect(); }
}
function drawResults() {
const r = results;
if (!r) return;
ctx.fillStyle = COL.scrim; ctx.fillRect(0, 0, W, H);
panel(ctx, 170, 56, 620, 488);
ctx.textAlign = 'center';
ctx.font = F_D46; ctx.fillStyle = COL.head; ctx.fillText('Finish!', W / 2, 112);
ctx.font = F_S16; ctx.fillStyle = COL.body; ctx.fillText(r.name, W / 2, 140);
drawMedal(ctx, 290, 222, 40, r.medal);
ctx.font = F_D20; ctx.fillStyle = MEDAL_COL[r.medal]; ctx.fillText(r.medalName, 290, 292);
if (r.medal > r.prevMedal && r.prevMedal > 0) { ctx.font = F_L11; ctx.fillStyle = COL.ok; ctx.fillText('MEDAL UPGRADE', 290, 310); }
ctx.textAlign = 'left';
ctx.font = F_L11; ctx.fillStyle = COL.dim; ctx.fillText('TIME', 400, 180);
ctx.font = F_M44; ctx.fillStyle = COL.head; ctx.fillText(r.timeStr, 398, 224);
ctx.font = F_L11; ctx.fillStyle = COL.dim; ctx.fillText('FAULTS', 400, 254); ctx.fillText('FLIPS', 500, 254);
ctx.font = F_M20; ctx.fillStyle = r.faults ? COL.danger : COL.ok; ctx.fillText(r.faultStr, 400, 278);
ctx.fillStyle = '#8ff3ff'; ctx.fillText(r.flipStr, 500, 278);
ctx.font = F_S14;
if (r.record) { ctx.fillStyle = COL.ok; ctx.fillText(r.recordStr, 400, 306); }
else { ctx.fillStyle = COL.body; ctx.fillText(r.recordStr, 400, 306); }
ctx.textAlign = 'center';
ctx.font = F_B14; ctx.fillStyle = COL.body; ctx.fillText(r.nextMsg, W / 2, 342);
ctx.font = F_S14; ctx.fillStyle = COL.ok;
for (let i = 0; i < r.unlocks.length; i++) ctx.fillText(r.unlocks[i], W / 2, 366 + i * 20);
if (r.lockMsg) { ctx.fillStyle = COL.hi; ctx.fillText(r.lockMsg, W / 2, 366 + r.unlocks.length * 20); }
ctx.font = F_S18; ctx.fillStyle = COL.head; ctx.fillText(r.totalLine, W / 2 - (r.newBest ? 50 : 0), 424);
if (r.newBest) { ctx.fillStyle = COL.hi; ctx.textAlign = 'left'; ctx.fillText('New best!', W / 2 + 40, 424); ctx.textAlign = 'center'; }
for (let i = 0; i < 3; i++) { const b = RES_BTNS[i]; pill(b[0], b[1], b[2], b[3], b[4], i === resFocus, i !== 0 || r.hasNext); }
if (overT >= 0.6) {
ctx.globalAlpha = blink(); ctx.font = F_S16; ctx.fillStyle = COL.hi;
ctx.fillText((touchUI ? RES_ACT_T : RES_ACT_K)[resFocus], W / 2, 512);
ctx.globalAlpha = 1;
if (!touchUI) { ctx.font = F_B13; ctx.fillStyle = COL.dim; ctx.fillText('Left / Right choose  \u00B7  R retry  \u00B7  T tracks', W / 2, 532); }
}
}
function resultsClick(x, y) {
for (let i = 0; i < 3; i++) if (inRect(RES_BTNS[i], x, y)) { if (i === 0 && !results.hasNext) return; resultsGo(i); return; }
resultsGo(resFocus);
}

const NPL = 8, NBUF = 8, PEN = 5000, NET_DT = 0.05, QUIET = 8;   // pose: [hostTime, x, y, angle, lean, phase, faults, respawns]
const GH_COL = ['#9fe6ff', '#ffb35c', '#c6ff3d', '#ff8ad8'], ORDS = ['', '1st', '2nd', '3rd', '4th'], ORD = [0, 0, 0, 0];
const ON_GO = [300, 304, 360, 50], ON_BACK = [20, 22, 100, 34], ON_LBL = ['RACES', 'WINS', 'PODIUMS'];
const LB_Y = [96, 164, 232], LB_X = 60, LB_W = 460, LB_H = 58, LB_START = [60, 314, 220, 46], LB_LEAVE = [300, 314, 220, 46], LB_LBL = ['TRACK', 'TRACK POOL', 'BIKES'];
const OM_BOX = [320, 196, 320, 214], OM_RES = [350, 262, 260, 44], OM_LEAVE = [350, 316, 260, 44];
const NR_BTNS = [[246, 446, 150, 42, 'REMATCH'], [405, 446, 150, 42, 'NEXT TRACK'], [564, 446, 150, 42, 'LEAVE']];
const NR_ACT = ['Press Space for a rematch', 'Press Space for the next track', 'Press Space to leave the room'];
const RPZ = newPose(); RPZ.ghost = true;
let N = null, nOpen = false, nTok = 0, netMsg = '', omenu = false;
const orec = { r: 0, w: 0, p: 0 };   // local online record: races, wins, podiums
