if (!N) return;
const lv = N.host ? 4 : 0;
if (code === 'Escape' || code === 'Backspace') { if (N.foc === lv) netLeave(); else N.foc = lv; return; }
if (!N.host) { if (go && N.foc === 0) netLeave(); return; }
