const GAME_KEYS = { KeyW: 1, KeyA: 1, KeyS: 1, KeyD: 1, ArrowUp: 1, ArrowDown: 1, ArrowLeft: 1, ArrowRight: 1, Space: 1, Enter: 1, NumpadEnter: 1, KeyR: 1, Backspace: 1, KeyP: 1, Escape: 1, KeyT: 1, KeyG: 1 };
